'use strict';

// Runtime device driver for BrowserStack cloud Detox sessions on iOS simulators. Extends
// detox's IosDriver (sync settings, shake, orientation and getPlatform() all go over the
// WS client), NOT SimulatorDriver — that one drives a local simulator through applesimutils
// and XCUITest, neither of which can reach a cloud device.
//
// The device host launches the app with -detoxServer / -detoxSessionId as soon as the
// session is allocated. launch / terminate still go through the same CloudPlatform action
// as Android: its response carries the cloud session id, and hosts that implement the iOS
// app lifecycle act on it. Hosts that only acknowledge it leave the app running.
//
// detox is resolved from process.cwd() (the customer's install) — the SDK package
// itself has no detox dependency.
const path = require('path');

const detoxRoot = path.dirname(require.resolve('detox/package.json', {paths: [process.cwd()]}));
const IosDriver = require(path.join(detoxRoot, 'src/devices/runtime/drivers/ios/IosDriver'));
const DetoxRuntimeError = require(path.join(detoxRoot, 'src/errors/DetoxRuntimeError'));
const log = require(path.join(detoxRoot, 'src/utils/logger')).child({cat: 'device'});

const {executeCloudPlatform} = require('../cloudPlatformAction');

const TERMINATE_DISCONNECT_TIMEOUT_MS = 15000;
const PAYLOAD_FILE_HINT = 'Detox passes this payload as a file on this machine, which a BrowserStack iOS simulator cannot read.';

const unsupported = (api, hint) => {
  throw new DetoxRuntimeError({
    message: `device.${api}() is not supported on BrowserStack iOS simulators.`,
    hint
  });
};

class CloudIosRuntimeDriver extends IosDriver {
  constructor(deps) {
    super(deps);

    this.launched = false;
    this.relaunchIgnored = false;
  }

  _cloud(method, extra) {
    return executeCloudPlatform(this.client, method, extra);
  }

  async _lifecycle(method, extra) {
    try {
      return await this._cloud(method, extra);
    } catch (err) {
      throw new DetoxRuntimeError({
        message: `The BrowserStack iOS simulator rejected ${method}.`,
        hint: 'Every spec file gets a fresh app. Within a file, use device.reloadReactNative() or device.openURL() instead of a new instance.',
        debugInfo: err && err.message
      });
    }
  }

  // The host relaunches with its own detox args and ignores any sent here, so none are: they
  // would only carry detoxServer, whose ?caps= holds the credentials. A URL is delivered over
  // the client once the app is up instead of riding detoxURLOverride.
  async launchApp(bundleId, launchArgs, languageAndLocale) { // eslint-disable-line no-unused-vars
    const relaunch = this.launched;
    if (!relaunch) {
      // The app is already running; this call is only for the session id in the response.
      try {
        await this._cloud('launchApp');
      } catch (err) {
        // The launch itself already happened host-side, but without this response the cloud
        // session id is never recorded, so the session cannot be marked.
        log.warn(`BrowserStack did not acknowledge the initial launchApp, so this session may not be marked: ${err && err.message}`);
      }
      this.launched = true;
    }

    // Rejected before any relaunch so an unsupported payload never restarts the app.
    if (launchArgs && launchArgs.detoxUserNotificationDataURL) {
      unsupported('launchApp({userNotification})', PAYLOAD_FILE_HINT);
    }
    if (launchArgs && launchArgs.detoxUserActivityDataURL) {
      unsupported('launchApp({userActivity})', PAYLOAD_FILE_HINT);
    }

    if (relaunch) {
      await this._lifecycle('launchApp');
    }

    const url = launchArgs && launchArgs.detoxURLOverride;
    if (url) {
      const sourceApp = launchArgs.detoxSourceAppOverride;
      await this.waitUntilReady();
      await this.client.deliverPayload(sourceApp ? {url, sourceApp} : {url});
    }

    return 0;
  }

  // RuntimeDevice terminates before the very first launch (newInstance defaults to true for an
  // app it has not launched). The host just started a fresh instance, so that one is a no-op.
  async terminate(bundleId) { // eslint-disable-line no-unused-vars
    if (!this.launched) {
      return;
    }
    await this._lifecycle('terminateApp');
    // A host that ignored one terminateApp ignores them all for the session, so later relaunches
    // skip the wait instead of each paying the full timeout.
    if (this.relaunchIgnored) {
      return;
    }
    if (!await this._waitForAppDisconnect()) {
      this.relaunchIgnored = true;
      log.warn('This BrowserStack iOS simulator did not restart the app for launchApp({newInstance: true}), '
        + 'so the tests in this spec file share one app instance. Use device.reloadReactNative() to reset the app between tests.');
    }
  }

  // A host that acknowledges terminateApp without acting on it leaves the app connected, and
  // detox's waitUntilDisconnected would then never settle. Resolves false on that timeout.
  async _waitForAppDisconnect() {
    let timer;
    const timeout = new Promise((resolve) => {
      timer = setTimeout(() => resolve(false), TERMINATE_DISCONNECT_TIMEOUT_MS);
    });
    try {
      return await Promise.race([this.client.waitUntilDisconnected().then(() => true), timeout]);
    } catch (ignored) {
      // The socket was already closed.
      return true;
    } finally {
      clearTimeout(timer);
    }
  }

  // launchApp delivers a URL itself once the app is up; a delayed URL would otherwise wait for a
  // relaunch that never comes.
  async deliverPayload(params) {
    if (params && (params.detoxUserNotificationDataURL || params.userNotification)) {
      unsupported(params.delayPayload ? 'launchApp({userNotification})' : 'sendUserNotification', PAYLOAD_FILE_HINT);
    }
    if (params && (params.detoxUserActivityDataURL || params.userActivity)) {
      unsupported(params.delayPayload ? 'launchApp({userActivity})' : 'sendUserActivity', PAYLOAD_FILE_HINT);
    }
    if (params && params.delayPayload) {
      return;
    }
    await super.deliverPayload(params);
  }

  async waitUntilReady() {
    try {
      await super.waitUntilReady();
    } catch (err) {
      await this._waitForAppDisconnect();
      throw err;
    }
  }

  async waitForActive() {
    return await this.client.waitForActive();
  }

  async waitForBackground() {
    return await this.client.waitForBackground();
  }

  // Stock detox has the app write the hierarchy to a path on the Mac it shares with the
  // simulator; on a cloud host that file never reaches the customer.
  async captureViewHierarchy() {
    unsupported('captureViewHierarchy');
  }

  async generateViewHierarchyXml(shouldInjectTestIds) {
    return await this.client.generateViewHierarchyXml({shouldInjectTestIds});
  }

  // The host installs the uploaded app before launching it; detox's own reinstall at init must
  // not fail the run.
  async installApp() {}

  async uninstallApp() {}

  async tap() {
    unsupported('tap', 'Tap an element instead: element(by.id(...)).tap().');
  }

  async longPress() {
    unsupported('longPress', 'Long-press an element instead: element(by.id(...)).longPress().');
  }

  async sendToHome() {
    unsupported('sendToHome');
  }

  async setLocation() {
    unsupported('setLocation');
  }

  async setPermissions() {
    unsupported('launchApp({permissions})');
  }

  async setBiometricEnrollment() {
    unsupported('setBiometricEnrollment');
  }

  async matchFace() {
    unsupported('matchFace');
  }

  async unmatchFace() {
    unsupported('unmatchFace');
  }

  async matchFinger() {
    unsupported('matchFinger');
  }

  async unmatchFinger() {
    unsupported('unmatchFinger');
  }

  async clearKeychain() {
    unsupported('clearKeychain');
  }

  async resetContentAndSettings() {
    unsupported('resetContentAndSettings');
  }

  async resetAppState() {
    unsupported('resetAppState');
  }

  async setStatusBar() {
    unsupported('setStatusBar');
  }

  async resetStatusBar() {
    unsupported('resetStatusBar');
  }

  async takeScreenshot() {
    unsupported('takeScreenshot');
  }
}

module.exports = CloudIosRuntimeDriver;
